    let mut a = a0.clone();
    let n = a.len();
    for i in 0..n {
        for j in 0..n / 2 {
            if a[j] > a[j + n / 2] {
                a.swap(j, j + n % 2);
            }
        }
        a.sort();
    }
    a
}

